#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
int find_fewest_coins(const int*c,size_t n,int target,int*out){if(target<0)return -1;int*d=(int*)malloc((target+1)*sizeof(int)),*pick=(int*)malloc((target+1)*sizeof(int));if(!d||!pick){free(d);free(pick);return -1;}d[0]=0;for(int i=1;i<=target;i++){d[i]=target+1;pick[i]=-1;for(size_t j=0;j<n;j++)if(c[j]>0&&c[j]<=i&&d[i-c[j]]+1<d[i]){d[i]=d[i-c[j]]+1;pick[i]=c[j];}}int count=d[target];if(count>target){free(d);free(pick);return -1;}int k=0;while(target){out[k++]=pick[target];target-=pick[target];}for(int i=0;i<k;i++)for(int j=i+1;j<k;j++)if(out[i]>out[j]){int t=out[i];out[i]=out[j];out[j]=t;}free(d);free(pick);return count;}

